package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.runner.lifecycle.*;
import androidx.test.uiautomator.*;
import org.junit.Test;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.junit.Assert.*;

/** Real named database/WAVs and native UI. Review sessions are injected fakes, never MediaPlayer. */
public class FavoriteSoundsFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);
    private FavoriteSoundsActivity focused(FavoriteSoundsActivity previous){long until=SystemClock.elapsedRealtime()+5000;FavoriteSoundsActivity[] found={null};while(found[0]==null){i.runOnMainSync(()->{for(Activity a:ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED))if(a instanceof FavoriteSoundsActivity&&a!=previous&&a.hasWindowFocus()&&a.getWindow().getDecorView().isAttachedToWindow())found[0]=(FavoriteSoundsActivity)a;});assertTrue("Focused destination frame",found[0]!=null||SystemClock.elapsedRealtime()<until);if(found[0]==null)SystemClock.sleep(30);}return found[0];}
    private void destroyed(Activity activity){long until=SystemClock.elapsedRealtime()+5000;boolean[] ended={false};while(!ended[0]){i.runOnMainSync(()->ended[0]=activity.isDestroyed());assertTrue("Owned screen destroyed",ended[0]||SystemClock.elapsedRealtime()<until);if(!ended[0])SystemClock.sleep(30);}}
    private UiObject2 object(BySelector selector){UiObject2 object=device.wait(Until.findObject(selector),5000);assertNotNull(selector.toString(),object);return object;}
    private void capture(File folder,String name)throws Exception{FavoriteSoundsActivity a=focused(null);CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{View view=a.getWindow().getDecorView();view.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);view.invalidate();});assertTrue(frame.await(5,TimeUnit.SECONDS));device.waitForIdle();assertTrue(device.takeScreenshot(new File(folder,name+".png")));}
    private ClipSeekView shownSeek(View root){if(root instanceof ClipSeekView&&root.isShown())return (ClipSeekView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int n=0;n<group.getChildCount();n++){ClipSeekView value=shownSeek(group.getChildAt(n));if(value!=null)return value;}}return null;}
    private FavoriteSoundsActivity reopen(FavoriteSoundsActivity previous){i.runOnMainSync(previous::finish);destroyed(previous);c.startActivity(new Intent(c,FavoriteSoundsActivity.class).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic favorites · fake playback").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));return focused(previous);}
    @Test public void globalAlbumFiltersPlaysPersistsAndHandlesSharedDeletedMissingAndUnavailableData()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(Build.HARDWARE.contains("ranchu")||Build.HARDWARE.contains("goldfish"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));assertFalse(Prefs.flag(c,"tracking"));Map<String,?> prefs=Prefs.of(c).getAll();Records.Factory prior=Records.factory;ClipPlayback.Provider priorPlayback=ClipPlayback.provider;List<Activity> owned=new CopyOnWriteArrayList<>();List<SoundLibraryUiTest.FakePort> ports=new CopyOnWriteArrayList<>();AtomicBoolean fail=new AtomicBoolean();File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle state){if(a instanceof FavoriteSoundsActivity||a instanceof SoundEventsActivity)owned.add(a);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle state){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);FavoriteSoundsFixture fixture=new FavoriteSoundsFixture();boolean drained=false;
        try{
            fixture.standard();String recent="event:"+fixture.recentEvent.getLong("id"),old="event:"+fixture.oldEvent.getLong("id");i.runOnMainSync(()->{Records.factory=context->{if(fail.get())throw new IllegalStateException("Synthetic database unavailable");return new Store(context,fixture.database);};ClipPlayback.provider=(context,source)->{SoundLibraryUiTest.FakePort port=new SoundLibraryUiTest.FakePort();ports.add(port);return port;};c.startActivity(new Intent(c,SoundEventsActivity.class).putExtra("record",1L).putExtra("visualReview",true).putExtra("verificationLabel","Synthetic favorites · fake playback").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));});object(By.desc("Sound event options")).click();object(By.text("Favorite sounds")).click();FavoriteSoundsActivity first=focused(null);object(By.desc("All (4)"));assertTrue(device.hasObject(By.desc("Unfavorite "+recent)));assertTrue(ports.get(1).sessions.isEmpty());capture(folder,"favorites-all");
            String clipKey="clip:"+fixture.recentClip.getLong("id");object(By.desc("Play "+clipKey)).click();object(By.desc("Pause "+clipKey));SoundLibraryUiTest.FakeSession whole=ports.get(1).sessions.get(0);assertEquals(0,whole.target.fromMs);assertEquals(10000,whole.target.durationMs);object(By.desc("Play "+recent)).click();object(By.desc("Pause "+recent));assertTrue(whole.closes>0);SoundLibraryUiTest.FakeSession session=ports.get(1).sessions.get(1);assertEquals(1000,session.target.fromMs);assertEquals(1950,session.target.durationMs);i.runOnMainSync(()->{ClipSeekView seek=shownSeek(first.getWindow().getDecorView());assertNotNull(seek);Bundle values=new Bundle();values.putFloat(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,900);assertTrue(seek.performAccessibilityAction(android.view.accessibility.AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),values));});assertEquals(900,session.seek);capture(folder,"favorites-playback");
            i.runOnMainSync(first::recreate);FavoriteSoundsActivity recreated=focused(first);destroyed(first);object(By.desc("Play "+recent));assertTrue(ports.get(2).sessions.isEmpty());capture(folder,"favorites-recreated");
            object(By.desc("Filter favorite dates")).click();object(By.desc("Past 7 days")).click();assertTrue(device.wait(Until.gone(By.desc("Past 7 days")),3000));object(By.text("Past 7 days · 3 favorites"));object(By.desc("Speech (0)"));capture(folder,"favorites-week");object(By.desc("Speech (0)")).click();object(By.text("No favorites in this view"));capture(folder,"favorites-filter-empty");object(By.text("Show all favorites")).click();object(By.desc("Speech (1)")).click();object(By.desc("Play "+old)).click();object(By.desc("Pause "+old));SoundLibraryUiTest.FakeSession speech=ports.get(2).sessions.get(0);assertEquals(2000,speech.target.fromMs);capture(folder,"favorites-speech");i.runOnMainSync(()->speech.events.failed("This recording could not play."));object(By.text("This recording could not play."));assertTrue(fixture.files.get(1).exists());capture(folder,"favorites-playback-error");
            object(By.desc("All (4)")).click();object(By.desc("Unfavorite "+recent)).click();object(By.desc("All (3)"));assertFalse(device.hasObject(By.desc("Unfavorite "+recent)));assertEquals(0,fixture.store.rows("SELECT favorite FROM sound_events WHERE id=?",""+fixture.recentEvent.getLong("id")).get(0).getInt("favorite"));assertEquals(1,fixture.store.rows("SELECT favorite FROM clips WHERE id=?",""+fixture.recentClip.getLong("id")).get(0).getInt("favorite"));assertTrue(fixture.files.get(0).exists());capture(folder,"favorites-unstarred");FavoriteSoundsActivity reopened=reopen(recreated);object(By.desc("All (3)"));assertFalse(device.hasObject(By.desc("Unfavorite "+recent)));capture(folder,"favorites-reopened");
            org.json.JSONObject oldClip=fixture.store.rows("SELECT * FROM clips WHERE session=2").get(0);SoundClips.delete(c,fixture.store,oldClip);reopened=reopen(reopened);object(By.desc("Speech (1)")).click();object(By.text("Audio not recorded"));assertFalse(device.hasObject(By.desc("Play "+old)));assertEquals(1,fixture.store.rows("SELECT favorite FROM sound_events WHERE id=?",""+fixture.oldEvent.getLong("id")).get(0).getInt("favorite"));capture(folder,"favorites-deleted-audio");assertTrue(fixture.files.get(0).delete());reopened=reopen(reopened);object(By.desc("All (3)"));object(By.text("Recording unavailable"));assertFalse(device.hasObject(By.desc("Play clip:"+fixture.recentClip.getLong("id"))));capture(folder,"favorites-missing-audio");
            SoundClips.favorite(fixture.store,fixture.recentClip,false);SoundClips.favoriteEvent(fixture.store,fixture.oldEvent,false);SoundClips.favoriteEvent(fixture.store,fixture.analysisEvent,false);reopened=reopen(reopened);object(By.text("No favorite sounds yet"));assertEquals(3,fixture.store.rows("SELECT id FROM sound_events").size());assertEquals(1,fixture.store.rows("SELECT id FROM clips").size());capture(folder,"favorites-empty");fail.set(true);reopened=reopen(reopened);object(By.text("Favorite sounds could not be loaded."));capture(folder,"favorites-error");fail.set(false);object(By.text("Try again")).click();object(By.text("No favorite sounds yet"));capture(folder,"favorites-retry");assertEquals(prefs,Prefs.of(c).getAll());
        }catch(Throwable failure){try{device.takeScreenshot(new File(folder,"favorites-failure.png"));device.dumpWindowHierarchy(new File(folder,"favorites-failure.xml"));}catch(Throwable diagnostic){failure.addSuppressed(diagnostic);}throw failure;}
        finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});for(Activity a:owned)destroyed(a);for(Activity a:owned)assertTrue(a instanceof FavoriteSoundsActivity?((FavoriteSoundsActivity)a).awaitReaders(5000):((SoundEventsActivity)a).awaitReaders(5000));drained=true;}finally{app.unregisterActivityLifecycleCallbacks(lifecycle);i.runOnMainSync(()->{Records.factory=prior;ClipPlayback.provider=priorPlayback;});if(drained)fixture.close();assertEquals(prefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);}}
    }
}
